export type KnowledgeCardsKey = keyof typeof zh

export function t(locale: { zh: typeof zh; en: typeof en } | undefined, key: KnowledgeCardsKey, params?: Record<string, string | number>): string {
  const dict = locale?.zh ?? zh
  let template: string = dict[key]
  if (params !== undefined) {
    for (const [name, value] of Object.entries(params)) {
      template = template.replace(`{${name}}`, String(value))
    }
  }
  return template
}

export { zh, en }
